@tl.core._aggregate
class CopyToken:
	position: gl.tensor

	def __init__(self, position):
		self.position = position


@tl.core._aggregate
class CopyPipeline:
	current: gl.tensor

	def __init__(self, current):
		self.current = current

	@participant2
	@participant4.jit
	def make():
		return CopyPipeline(gl.to_tensor(0))

	@participant4.jit
	def make_token(self):
		return CopyToken(gl.to_tensor(-1))

	@tl.core.must_use_result
	@participant4.jit
	def load(self, destination, source, mask=None):
		triton.experimental.gluon.language.nvidia.ampere.async_copy.async_copy_global_to_shared(
			destination, source, mask
		)
		triton.experimental.gluon.language.nvidia.ampere.async_copy.commit_group()
		return (CopyPipeline(self.current + 1), CopyToken(self.current))

	@participant4.jit
	def wait(self, token: CopyToken):
		count = self.current - 1 - token.position
		for i in gl.static_range(4):
			if count <= i:
				triton.experimental.gluon.language.nvidia.ampere.async_copy.wait_group(
					i
				)
				return
		gl.device_assert(False, "Pipeline too deep")


@tl.core._aggregate
class DotAccumulator:
	position: gl.tensor
	result: gl.tensor
	accumulator: (
		triton.experimental.gluon.language.nvidia.hopper.warpgroup_mma_accumulator
	)

	def __init__(self, position, result, accumulator):
		self.position = position
		self.result = result
		self.accumulator = accumulator

	@participant4.jit
	def update_dot(self, position, accumulator):
		return DotAccumulator(position, self.result, accumulator)

	@participant4.jit
	def update_wait(self, result):
		return DotAccumulator(self.position, result, self.accumulator)


@tl.core._aggregate
class DotPipeline:
	current: gl.tensor

	def __init__(self, current):
		self.current = current

	@participant2
	@participant4.jit
	def make():
		return DotPipeline(gl.to_tensor(0))

	@participant4.jit
	def shared_fence(self):
		triton.experimental.gluon.language.nvidia.hopper.fence_async_shared()

	@tl.core.must_use_result
	@participant4.jit
	def dot(self, dot: "Dot", a, b, c: DotAccumulator):
		accumulator_result = (
			triton.experimental.gluon.language.nvidia.hopper.warpgroup_mma(
				a, b, c.result, is_async=True
			)
		)
		return (
			DotPipeline(self.current + 1),
			c.update_dot(self.current, accumulator_result),
		)

	@tl.core.must_use_result
	@participant4.jit
	def dot_sync(self, dot: "Dot", a, b, c=None):
		(pipeline, accumulator) = self.dot(dot, a, b, dot.make_accumulator(c))
		result = pipeline.wait(accumulator)
		return (pipeline, result.result)

	@participant2
	@participant4.jit
	def _wait(count, deps):
		for i in gl.static_range(4):
			if count <= i:
				return (
					triton.experimental.gluon.language.nvidia.hopper.warpgroup_mma_wait(
						i, deps=deps
					)
				)
		gl.device_assert(False, "Pipeline too deep")

	@tl.core.must_use_result
	@participant4.jit
	def wait(self, accumulator: DotAccumulator):
		return accumulator.update_wait(
			DotPipeline._wait(
				self.current - 1 - accumulator.position, (accumulator.accumulator,)
			)
		)


@tl.core._aggregate
class Dot:
	a_shape: gl.tuple
	b_shape: gl.tuple
	c_shape: gl.tuple
	a_layout: gl.constexpr
	b_layout: gl.constexpr
	c_layout: gl.constexpr
	a_alternate_layout: gl.constexpr

	def __init__(
		self,
		a_shape,
		b_shape,
		c_shape,
		a_layout,
		b_layout,
		c_layout,
		a_alternate_layout,
	):
		self.a_shape = a_shape
		self.b_shape = b_shape
		self.c_shape = c_shape
		self.a_layout = a_layout
		self.b_layout = b_layout
		self.c_layout = c_layout
		self.a_alternate_layout = a_alternate_layout

	@participant2
	@participant4.jit
	def make(a_shape, b_shape, in_dtype, out_dtype):
		max_n: gl.constexpr = b_shape[1] * a_shape[0] // (gl.num_warps() * 16)
		c_layout: gl.constexpr = gl.NVMMADistributedLayout(
			[3, 0],
			warps_per_cta=[4, gl.num_warps() // 4],
			instr_shape=[
				16,
				max_n if max_n < b_shape[1] else b_shape[1],
				256 // in_dtype.primitive_bitwidth,
			],
		)
		a_layout: gl.constexpr = gl.NVMMASharedLayout.get_default_for(a_shape, in_dtype)
		b_layout: gl.constexpr = gl.NVMMASharedLayout.get_default_for(b_shape, in_dtype)
		a_alternate_layout: gl.constexpr = gl.DotOperandLayout(
			0, c_layout, 32 // in_dtype.primitive_bitwidth
		)

		return Dot(
			a_shape,
			b_shape,
			(a_shape[0], b_shape[1]),
			a_layout,
			b_layout,
			c_layout,
			a_alternate_layout,
		)

	@participant4.jit
	def make_accumulator(self, value=None):
		result = (
			gl.zeros(self.c_shape, gl.float32, self.c_layout)
			if value is None
			else value
		)
		return DotAccumulator(
			gl.to_tensor(-1),
			result,
			triton.experimental.gluon.language.nvidia.hopper.warpgroup_mma_init(result),
		)


class PipelineRange(typing.NamedTuple):
	start: gl.tensor
	end: gl.tensor
	step: gl.tensor


@tl.core._aggregate
class PipelineStage:
	base_index: gl.tensor
	offset: gl.constexpr
	range: gl.tuple

	def __init__(self, base_index, offset, range):
		self.base_index = base_index
		self.offset = offset
		self.range = range

	@participant4.jit
	def raw_index(self):
		return self.base_index + self.offset

	@participant4.jit
	def index(self):
		return self.raw_index() * self.range.step

	@participant4.jit
	def started(self):
		return self.range.start <= self.index()

	@participant4.jit
	def active(self):
		return self.started() and self.index() < self.range.end


@tl.core._aggregate
class PipelineSchedule:
	stages: gl.constexpr
	range: gl.tuple | gl.constexpr
	index: gl.tensor

	def __init__(self, stages, range, index):
		self.stages = stages
		self.range = range
		self.index = index

	@participant2
	@participant4.jit
	def make(stages, start=None, end=None, step=None):
		if start is None:
			range = None
		elif end is None:
			range = PipelineRange(0, start, 1)
		elif step is None:
			range = PipelineRange(start, end, 1)
		else:
			range = PipelineRange(start, end, step)
		return PipelineSchedule(gl.constexpr(stages), range, gl.to_tensor(0))

	@participant4.jit
	def __getitem__(self, stage) -> PipelineStage:
		for i in gl.static_range(len(self.stages)):
			if stage == self.stages[i]:
				return PipelineStage(self.index, -i, self.range)

	@participant4.jit
	def distance(self, stage1, stage2):
		return self[stage1].offset - self[stage2].offset

	@tl.core.must_use_result
	@participant4.jit
	def advance(self):
		return PipelineSchedule(self.stages, self.range, self.index + 1)

	@participant4.jit
	def active(self):
		return (
			self.range.start + (self.index - len(self.stages)) * self.range.step
			< self.range.end
		)

# ------------------------------------------------------------------------------
# END IGNORED REGION
# ------------------------------------------------------------------------------


@participant4.jit
def pipelined_double_matmul(
	a_ptr,
	b_ptr,
	c_ptr,
	M: gl.constexpr,
	K: gl.constexpr,
	N: gl.constexpr,
	BLOCK_M: gl.constexpr,
	BLOCK_K: gl.constexpr,
	BLOCK_N: gl.constexpr,
):
	copy = CopyPipeline.make()
	pipeline = DotPipeline.make()

	num_k_tiles = gl.cdiv(K, BLOCK_K)
	schedule = PipelineSchedule.make(
		("load", "compute"),
		gl.to_tensor(0),
		gl.to_tensor(num_k_tiles),
		gl.to_tensor(BLOCK_K),
	)

	dot = Dot.make((BLOCK_M, BLOCK_K), (BLOCK_K, BLOCK_N), gl.float16, gl.float32)

	a_token = copy.make_token()
	a_smem = gl.allocate_shared_memory(gl.float16, (BLOCK_M, BLOCK_K), dot.a_layout)

	a_reg = gl.zeros((BLOCK_M, BLOCK_K), gl.float16, dot.a_alternate_layout)

	b_token = copy.make_token()
	b_smem = gl.allocate_shared_memory(gl.float16, (BLOCK_K, BLOCK_N), dot.b_layout)

	acc = gl.zeros(dot.c_shape, gl.float32, dot.c_layout)

	a_desc = Descriptor.make_inline(
		a_ptr,
		size=(M, K),
		stride=(K, 1),
		block_shape=(BLOCK_M, BLOCK_K),
		layout=Layout.gmem((BLOCK_M, BLOCK_K), gl.float16).layout,
	)

	b_desc = Descriptor.make_inline(
		b_ptr,
		size=(K, N),
		stride=(N, 1),
		block_shape=(BLOCK_K, BLOCK_N),
		layout=Layout.gmem((BLOCK_K, BLOCK_N), gl.float16).layout,
	)

	c_desc = Descriptor.make_inline(
		c_ptr,
		size=(M, N),
		stride=(N, 1),
		block_shape=(BLOCK_M, BLOCK_N),
		layout=dot.c_layout,
	)

	while schedule.active():
		# COMPUTE STAGE: Wait/pull to registers, then double and dot
		if schedule["compute"].active():
			k_idx = schedule["compute"].index()

			# Wait and pull to registers (frees shared memory)
			copy.wait(a_token)
			pl.exit_scope("a_load")
			a_reg = a_smem.load(a_reg.type.layout)

		# LOAD STAGE: Load next iteration's a (happens after pull frees the buffer)
		if schedule["load"].active():
			k_idx = schedule["load"].index()

			pl.enter_scope("a_load")
			(copy, a_token) = copy.load(
				a_smem,
				a_desc.data + a_desc.offsets((0, k_idx)),
			)

			# Load b for this iteration
			(copy, b_token) = copy.load(
				b_smem, b_desc.data + b_desc.offsets((k_idx, 0))
			)

		# COMPUTE STAGE continued: Double and do matrix multiply
		if schedule["compute"].active():
			k_idx = schedule["compute"].index()

			# Double a
			a_doubled = a_reg * 2.0

			# Wait for b to be loaded
			copy.wait(b_token)

			# Sync before compute
			pipeline.shared_fence()

			# Matrix multiply
			(pipeline, result) = pipeline.dot_sync(dot, a_doubled, b_smem, acc)
			acc = result

		schedule = schedule.advance()

	gl.store(c_desc.data + c_desc.offsets((0, 0)), acc)


if __name__ == "__main__":
	M = 64
	K = 256
	N = 64
	BLOCK_M = 64
	BLOCK_K = 64
	BLOCK_N = 64

	a = torch.randn(M, K, dtype=torch.float16, device="cuda")
	b = torch.randn(K, N, dtype=torch.float16, device="cuda")
	c = torch.zeros(M, N, dtype=torch.float32, device="cuda")

	proton.start(
		"test",
		data="trace",
		backend="instrumentation",
		mode=pmode.Default(),
	)

	pipelined_double_matmul[(1,)](
		a,
		b,
		c,
		M=M,
		K=K,
		N=N,
		BLOCK_M=BLOCK_M,
		BLOCK_K=BLOCK_K,
		BLOCK_N=BLOCK_N,
	)

	proton.finalize()
